      "interpretation": "Acima da MM20 e EMAs — preço com viés positivo no curtíssimo prazo."
    },
    {
      "indicator": "MM20",
      "reading": "≈ 36.6",
      "interpretation": "MM20 acima da MM50 — confirmação de tendência de curto prazo para alta."
    },
    {
      "indicator": "MM50",
      "reading": "≈ 35.8",
      "interpretation": "MM50 ascendendo e acima da MM200 — tendência de médio prazo orientada para cima."
    },
    {
      "indicator": "MM200",
      "reading": "≈ 33.6",
      "interpretation": "MM200 em suporte ascendente — estrutura de longo prazo neutra/altista."
    },
    {
      "indicator": "EMA9 / EMA21",
      "reading": "≈ 36.7 / 36.5",
      "interpretation": "EMAs rápidas acima das médias mais lentas — sinal de continuidade de alta de curto prazo."
    },
    {
      "indicator": "MACD (12,26,9)",
      "reading": "MACD ≈ 0.30; signal ≈ 0.28; histograma ≈ +0.02",
      "interpretation": "MACD positivo e ligeiramente acima da linha de sinal; momentum presente, mas enfraquecido (histograma achatado)."
    },
    {
      "indicator": "Bandas de Bollinger (20, 2σ)",
      "reading": "Preço próximo da banda superior (upper ≈ 37.2–37.5; middle ≈ 36.6)",
      "interpretation": "Volatilidade moderada; proximidade da banda superior aponta para possível resistência ou correção de curtíssimo prazo."
    },
    {
      "indicator": "RSI14",
      "reading": "≈ 55–58",
      "interpretation": "Leitura neutra a levemente otimista — sem sobrecompra; espaço para continuidade, porém sem impulso forte."
    },
    {
      "indicator": "Volume",
      "reading": "Volume recente moderado; sem picos de confirmação",
      "interpretation": "Subidas recentes com volume fraco/moderado reduzem a convicção do rali; buscar aumento de volume para validação."
    }
  ]
